### proto/harness/reasoning/v1/common.proto
syntax = "proto3";

package harness.reasoning.v1;

import "google/protobuf/timestamp.proto";

option go_package = "github.com/Standard-Syntax/basic/go/gen/harness/reasoning/v1;reasoningv1";

enum ReasoningStage {
  REASONING_STAGE_UNSPECIFIED = 0;
  REASONING_STAGE_SPECIFICATION = 1;
  REASONING_STAGE_PLANNING = 2;
  REASONING_STAGE_IMPLEMENTATION = 3;
  REASONING_STAGE_REVIEW = 4;
}

enum AuthorityMode {
  AUTHORITY_MODE_UNSPECIFIED = 0;
  AUTHORITY_MODE_PROPOSAL_ONLY = 1;
}

message AuthorityConstraints {
  AuthorityMode mode = 1;
  bool may_mutate_kernel_state = 2;
  bool may_execute_commands = 3;
  bool may_modify_files = 4;
  bool may_expand_scope = 5;
  bool may_approve_work = 6;
}

message ReasoningBudget {
  uint64 maximum_input_tokens = 1;
  uint64 maximum_output_tokens = 2;
  uint32 maximum_provider_requests = 3;
}

message ArtifactDigest {
  string artifact_uri = 1;
  string sha256 = 2;
}

message ReasoningRequestEnvelope {
  string schema_version = 1;
  string request_id = 2;
  string run_id = 3;
  optional string task_id = 4;
  ReasoningStage stage = 5;
  uint32 attempt = 6;
  google.protobuf.Timestamp created_at = 7;
  google.protobuf.Timestamp expires_at = 8;
  AuthorityConstraints authority = 9;
  ReasoningBudget budget = 10;
  repeated ArtifactDigest input_artifacts = 11;
  string agent_manifest_digest = 12;
}

message ProposalIdentity {
  string schema_version = 1;
  string request_id = 2;
  string run_id = 3;
  optional string task_id = 4;
  ReasoningStage stage = 5;
  uint32 attempt = 6;
  string agent_manifest_digest = 7;
  repeated string input_artifact_digests = 8;
}

enum RejectionCode {
  REJECTION_CODE_UNSPECIFIED = 0;
  REJECTION_CODE_SCHEMA_INVALID = 1;
  REJECTION_CODE_REQUEST_MISMATCH = 2;
  REJECTION_CODE_AUTHORITY_VIOLATION = 3;
  REJECTION_CODE_SCOPE_VIOLATION = 4;
  REJECTION_CODE_REQUIRED_COVERAGE_MISSING = 5;
}

message RejectionDetail {
  string field = 1;
  string message = 2;
}

message ProposalRejection {
  RejectionCode code = 1;
  string summary = 2;
  repeated RejectionDetail details = 3;
  bool retryable = 4;
  string request_id = 5;
  string run_id = 6;
  optional string task_id = 7;
  uint32 attempt = 8;
  google.protobuf.Timestamp timestamp = 9;
}
### proto/harness/reasoning/v1/implementation.proto
syntax = "proto3";

package harness.reasoning.v1;

import "harness/reasoning/v1/common.proto";

option go_package = "github.com/Standard-Syntax/basic/go/gen/harness/reasoning/v1;reasoningv1";

message RepositoryContextFile {
  string path = 1;
  string sha256 = 2;
  string content = 3;
}

message ImplementationRequest {
  ReasoningRequestEnvelope envelope = 1;
  string approved_task_id = 16;
  string approved_task_digest = 17;
  string approved_specification_id = 18;
  string approved_specification_digest = 19;
  string base_commit = 20;
  repeated string readable_paths = 21;
  repeated string writable_paths = 22;
  repeated string prohibited_paths = 23;
  repeated string acceptance_criterion_ids = 24;
  repeated string available_check_ids = 25;
  repeated RepositoryContextFile repository_context = 26;
}

enum FileOperation {
  FILE_OPERATION_UNSPECIFIED = 0;
  FILE_OPERATION_CREATE = 1;
  FILE_OPERATION_UPDATE = 2;
  FILE_OPERATION_DELETE = 3;
}

message FileChange {
  string path = 1;
  FileOperation operation = 2;
  string expected_original_sha256 = 3;
  optional string replacement_content = 4;
  string rationale = 5;
  repeated string acceptance_criterion_ids = 6;
}

message ScopeChangeRequest {
  string summary = 1;
  repeated string requested_readable_paths = 2;
  repeated string requested_writable_paths = 3;
  repeated string requested_acceptance_criterion_ids = 4;
  repeated string requested_check_ids = 5;
}

message ImplementationProposal {
  ProposalIdentity identity = 1;
  string approved_task_id = 16;
  string approved_task_digest = 17;
  string approved_specification_digest = 18;
  string summary = 19;
  repeated FileChange changes = 20;
  repeated string requested_declared_check_ids = 21;
  repeated string assumptions = 22;
  repeated string unresolved_questions = 23;
  optional ScopeChangeRequest scope_change_request = 24;
}
### proto/harness/reasoning/v1/planning.proto
syntax = "proto3";

package harness.reasoning.v1;

import "harness/reasoning/v1/common.proto";

option go_package = "github.com/Standard-Syntax/basic/go/gen/harness/reasoning/v1;reasoningv1";

message RepositoryEntry {
  string path = 1;
  string kind = 2;
  string sha256 = 3;
}

message TaskPlanningRequest {
  ReasoningRequestEnvelope envelope = 1;
  string approved_specification_id = 16;
  string approved_specification_digest = 17;
  repeated RepositoryEntry repository_map = 18;
  repeated string readable_paths = 19;
  repeated string writable_paths = 20;
  repeated string prohibited_paths = 21;
  uint32 task_count_limit = 22;
  uint32 parallelism_limit = 23;
  repeated string acceptance_criterion_ids = 24;
}

message TaskDependency {
  string task_id = 1;
}

message PlannedTask {
  string task_id = 1;
  string objective = 2;
  repeated TaskDependency dependencies = 3;
  repeated string acceptance_criterion_ids = 4;
  repeated string readable_paths = 5;
  repeated string writable_paths = 6;
  repeated string prohibited_paths = 7;
  repeated string exclusive_resources = 8;
  repeated string required_check_ids = 9;
  repeated string stop_conditions = 10;
}

message TaskGraphProposal {
  ProposalIdentity identity = 1;
  string approved_specification_id = 16;
  string approved_specification_digest = 17;
  repeated PlannedTask tasks = 18;
  repeated string assumptions = 19;
  repeated string unresolved_scope_questions = 20;
}
### proto/harness/reasoning/v1/review.proto
syntax = "proto3";

package harness.reasoning.v1;

import "google/protobuf/timestamp.proto";
import "harness/reasoning/v1/common.proto";
import "harness/reasoning/v1/implementation.proto";

option go_package = "github.com/Standard-Syntax/basic/go/gen/harness/reasoning/v1;reasoningv1";

message ReviewCandidateIdentity {
  string approved_specification_digest = 1;
  string approved_task_digest = 2;
  string base_commit = 3;
  string candidate_commit = 4;
  string implementation_proposal_digest = 5;
}

message ActualDiffFile {
  string path = 1;
  FileOperation operation = 2;
  string before_sha256 = 3;
  string after_sha256 = 4;
}

message ScopeReport {
  repeated string authorized_changed_paths = 1;
  repeated string unexpected_changed_paths = 2;
}

message IndependentEvidence {
  string evidence_id = 1;
  string check_id = 2;
  string candidate_commit = 3;
  int32 exit_code = 4;
  string output_sha256 = 5;
  string artifact_uri = 6;
  google.protobuf.Timestamp started_at = 7;
  google.protobuf.Timestamp completed_at = 8;
}

message AcceptanceEvidence {
  string acceptance_criterion_id = 1;
  repeated string evidence_ids = 2;
}

message ReviewPolicy {
  repeated FindingSeverity blocking_severities = 1;
  bool report_unrequested_changes = 2;
}

message ReviewRequest {
  ReasoningRequestEnvelope envelope = 1;
  ReviewCandidateIdentity candidate = 16;
  repeated ActualDiffFile actual_diff = 17;
  ScopeReport scope_report = 18;
  repeated IndependentEvidence independent_evidence = 19;
  repeated AcceptanceEvidence acceptance_coverage = 20;
  ReviewPolicy review_policy = 21;
  repeated string approved_acceptance_criterion_ids = 22;
  repeated string authorized_writable_paths = 23;
}

enum ReviewRecommendation {
  REVIEW_RECOMMENDATION_UNSPECIFIED = 0;
  REVIEW_RECOMMENDATION_REWORK_REQUIRED = 1;
  REVIEW_RECOMMENDATION_ADVISORY_ACCEPT = 2;
}

enum FindingSeverity {
  FINDING_SEVERITY_UNSPECIFIED = 0;
  FINDING_SEVERITY_INFO = 1;
  FINDING_SEVERITY_LOW = 2;
  FINDING_SEVERITY_MEDIUM = 3;
  FINDING_SEVERITY_HIGH = 4;
  FINDING_SEVERITY_CRITICAL = 5;
}

enum FindingCategory {
  FINDING_CATEGORY_UNSPECIFIED = 0;
  FINDING_CATEGORY_CORRECTNESS = 1;
  FINDING_CATEGORY_SECURITY = 2;
  FINDING_CATEGORY_SCOPE = 3;
  FINDING_CATEGORY_TESTING = 4;
  FINDING_CATEGORY_MAINTAINABILITY = 5;
  FINDING_CATEGORY_COMPATIBILITY = 6;
}

message ReviewFinding {
  string finding_id = 1;
  FindingSeverity severity = 2;
  FindingCategory category = 3;
  string summary = 4;
  repeated string evidence_references = 5;
}

message RequiredAction {
  string action_id = 1;
  string finding_id = 2;
  string description = 3;
}

message ResidualRisk {
  string risk_id = 1;
  string description = 2;
  FindingSeverity severity = 3;
}

message ReviewProposal {
  ProposalIdentity identity = 1;
  ReviewRecommendation recommendation = 16;
  repeated ReviewFinding findings = 17;
  repeated RequiredAction required_actions = 18;
  repeated string unrequested_changes = 19;
  repeated ResidualRisk residual_risks = 20;
  repeated string assumptions = 21;
}
### proto/harness/reasoning/v1/specification.proto
syntax = "proto3";

package harness.reasoning.v1;

import "harness/reasoning/v1/common.proto";

option go_package = "github.com/Standard-Syntax/basic/go/gen/harness/reasoning/v1;reasoningv1";

message SpecificationRequest {
  ReasoningRequestEnvelope envelope = 1;
  string problem_statement = 16;
  string desired_outcome = 17;
  repeated string known_constraints = 18;
  repeated string known_non_goals = 19;
  repeated string stakeholders = 20;
  optional string repository_summary = 21;
}

message AcceptanceCriterion {
  string criterion_id = 1;
  string description = 2;
  string verification_method = 3;
}

message SpecificationRisk {
  string risk_id = 1;
  string description = 2;
  string mitigation = 3;
}

message SpecificationQuestion {
  string question_id = 1;
  string question = 2;
  bool blocking = 3;
}

message SpecificationProposal {
  ProposalIdentity identity = 1;
  string title = 16;
  string goal = 17;
  repeated string actors = 18;
  repeated string constraints = 19;
  repeated string non_goals = 20;
  repeated AcceptanceCriterion acceptance_criteria = 21;
  repeated string assumptions = 22;
  repeated SpecificationRisk risks = 23;
  repeated SpecificationQuestion questions = 24;
}

